	private static final class CountingNativeSailStore extends NativeSailStore {
		private static final AtomicInteger CLOSE_COUNT = new AtomicInteger();

		private CountingNativeSailStore(File dataDirectory) throws IOException, SailException {
			super(dataDirectory, "spoc");
		}

		@Override
		public void close() throws SailException {
			CLOSE_COUNT.incrementAndGet();
			super.close();
		}
	}

	private static final class TestOverflowModel extends MemoryOverflowModel {
		private static final long serialVersionUID = 1L;

		private final FailureMode failureMode;
		private final Statement statement;
		private File dataDirectory;
		private SailStore createdStore;
		private boolean storeClosed;
		private boolean storeCloseHeldModelMonitor;

		private TestOverflowModel(FailureMode failureMode, Statement statement) {
			this.failureMode = failureMode;
			this.statement = statement;
		}

		@Override
		protected SailStore createSailStore(File dataDir) throws IOException, SailException {
			dataDirectory = dataDir;
			if (failureMode == FailureMode.STORE_CREATION) {
				throw new IOException("simulated store creation failure");
			}
			createdStore = mock(SailStore.class);
			doAnswer(invocation -> {
				storeClosed = true;
				storeCloseHeldModelMonitor = Thread.holdsLock(this);
				return null;
			}).when(createdStore).close();
			SailSource source = mock(SailSource.class);
			SailSink sink = mock(SailSink.class);
			SailDataset dataset = mock(SailDataset.class);
			when(createdStore.getExplicitSailSource()).thenReturn(source);
			when(source.sink(IsolationLevels.NONE)).thenReturn(sink);
			when(source.dataset(IsolationLevels.NONE)).thenReturn(dataset);
			doAnswer(invocation -> new TrackingIteration(statement)).when(dataset)
					.getStatements(any(), any(), any());
			if (failureMode == FailureMode.IMPORT) {
				doAnswer(invocation -> {
					throw new SailException("simulated native store import failure");
				}).when(sink).approveAll(anySet(), anySet());
			}
			return createdStore;
		}
	}

	private static final class TrackingIteration implements CloseableIteration<Statement> {
		private final Iterator<Statement> statements;

		private TrackingIteration(Statement statement) {
			statements = statement == null ? List.<Statement>of().iterator() : List.of(statement).iterator();
		}

		@Override
		public boolean hasNext() {
			return statements.hasNext();
		}

		@Override
		public Statement next() {
			return statements.next();
		}

		@Override
		public void remove() {
			statements.remove();
		}

		@Override
		public void close() {
		}
	}

	private static final class GcNotifications implements AutoCloseable {
		private final BlockingQueue<Boolean> notifications = new LinkedBlockingQueue<>();
		private final NotificationListener listener = (notification, handback) -> notifications.offer(Boolean.TRUE);
		private final List<NotificationEmitter> emitters = new ArrayList<>();

		private GcNotifications() {
			for (GarbageCollectorMXBean gcBean : ManagementFactory.getGarbageCollectorMXBeans()) {
				if (gcBean instanceof NotificationEmitter emitter) {
					emitter.addNotificationListener(listener, null, null);
					emitters.add(emitter);
				}
			}
		}

		private void requestGcAndAwait() throws InterruptedException {
			System.gc();
			assertThat(notifications.poll(30, TimeUnit.SECONDS)).isNotNull();
		}

		@Override
		public void close() throws Exception {
			for (NotificationEmitter emitter : emitters) {
				emitter.removeNotificationListener(listener);
			}
		}
	}
